/* AIVIC_FUNCTION_BUNDLE_START owner=validateSenderEmailFormat exports=validateSenderEmailFormat */
const __aivicBundle_50_validateSenderEmailFormat = (() => {
  function validateSenderEmailFormat(senderEmail: string): { isValid: boolean; error?: string } {
    // RFC 5322 simplified email validation
    // Basic checks for common invalid formats
    
    if (!senderEmail || typeof senderEmail !== 'string') {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    const trimmedEmail = senderEmail.trim();
  
    // Check for empty string
    if (trimmedEmail.length === 0) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Check for @ symbol presence and position
    const atCount = (trimmedEmail.match(/@/g) || []).length;
    if (atCount !== 1) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    const [localPart, domain] = trimmedEmail.split('@');
  
    // Validate local part (before @)
    if (!localPart || localPart.length === 0) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Check for spaces in local part
    if (localPart.includes(' ')) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Check for consecutive dots or leading/trailing dots
    if (localPart.startsWith('.') || localPart.endsWith('.') || localPart.includes('..')) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Validate domain part (after @)
    if (!domain || domain.length === 0) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Check for valid domain structure
    if (domain.startsWith('.') || domain.endsWith('.') || domain.includes('..')) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Domain must have at least one dot and valid TLD
    if (!domain.includes('.')) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    const domainParts = domain.split('.');
    
    // Check that domain parts are not empty
    for (const part of domainParts) {
      if (part.length === 0) {
        return {
          isValid: false,
          error: 'Invalid email format',
        };
      }
    }
  
    // TLD must be at least 2 characters
    const tld = domainParts[domainParts.length - 1];
    if (tld.length < 2) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    return {
      isValid: true,
    };
  }
  return { validateSenderEmailFormat };
})();
export const validateSenderEmailFormat = __aivicBundle_50_validateSenderEmailFormat.validateSenderEmailFormat;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateSenderEmailFormat */

